using System.Collections.Generic;public class Solution{string a,b;Dictionary<string,bool>m=new();bool F(int i,int j,int n){string key=$"{i},{j},{n}";if(m.TryGetValue(key,out bool v))return v;int[]c=new int[26];for(int k=0;k<n;k++){c[a[i+k]-'a']++;c[b[j+k]-'a']--;}foreach(int x in c)if(x!=0)return m[key]=false;if(a.Substring(i,n)==b.Substring(j,n))return m[key]=true;for(int k=1;k<n;k++)if(F(i,j,k)&&F(i+k,j+k,n-k)||F(i,j+n-k,k)&&F(i+k,j,n-k))return m[key]=true;return m[key]=false;}public bool IsScramble(string s1,string s2){a=s1;b=s2;return a.Length==b.Length&&F(0,0,a.Length);}}
